descriptor.templateCss:
#container .my-widget {
    font-family: sans-serif;
    padding: 10px;
    background: #f5f5f5;
}

#container .my-widget h3 {
    margin: 0 0 8px;
    font-size: 16px;
}

#container .my-widget ul {
    list-style: disc inside;
    margin: 0;
    padding: 0;
}

#container .my-widget li {
    margin: 2px 0;
}

descriptor.controllerScript:
// Called once after the widget is initialized
self.onInit = function() {
    // initialize an empty data array
    self.ctx.data = [];
  };
  
  // Called whenever the incoming data changes
  self.onDataUpdated = function() {
    var arr = [];
    // self.ctx.dataSources is an array of datasources
    if (self.ctx.dataSources && self.ctx.dataSources.length) {
      self.ctx.dataSources.forEach(function(ds) {
        (ds.data || []).forEach(function(point) {
          // point = [ timestamp, value ]
          arr.push(point[1]);
        });
      });
    }
    // expose to your template via ctx.data
    self.ctx.data = arr;
  };
  
  // Called if the widget container is resized
  self.onResize = function() {
    // no-op
  };
  
  // Metadata for dashboards (optional)
  self.typeParameters = function() {
    return {
      dataKeysOptional: true,
      datasourcesOptional: true,
      maxDatasources: 1,
      maxDataKeys: 0,
      singleEntity: true,
      previewWidth: '200px',
      previewHeight: '80px'
    };
  };
  
  // Expose any actions if needed (optional)
  self.actionSources = function() {
    return {
      'click': {
        name: 'widget-action.click',
        multiple: false
      }
    };
  };
